export type Level = "Dasar" | "Menengah" | "Lanjutan" | "Siap Ujian";

export interface CodeExample {
  title: string;
  lang: "json" | "bash" | "yaml";
  code: string;
}

export interface Section {
  heading: string;
  paragraphs: string[];
  codeExample?: CodeExample;
}

export interface Question {
  id: string;
  prompt: string;
  options: string[];
  answerIndex: number;
  explanation: string;
}

export interface Module {
  slug: string;
  title: string;
  level: Level;
  durationMinutes: number;
  intro: string;
  sections: Section[];
  keyPoints: string[];
  quiz: Question[];
}

export interface ExamInfo {
  questionCount: number;
  durationMinutes: number;
  passingScore: number;
}

export interface Track {
  id: string;
  slug: string;
  name: string;
  tagline: string;
  description: string;
  audience: string;
  color: "teal" | "amber" | "rose";
  icon: "server" | "activity" | "shield";
  examInfo: ExamInfo;
  modules: Module[];
  examQuestions: Question[];
}

import type { Module, Track } from "./types";
import { engineerTrack } from "./tracks/engineer";
import { observabilityTrack } from "./tracks/observability";
import { detectionTrack } from "./tracks/detection";

export const tracks: Track[] = [engineerTrack, observabilityTrack, detectionTrack];

export function getTrack(slug: string): Track | undefined {
  return tracks.find((t) => t.slug === slug);
}

export function getModule(
  trackSlug: string,
  moduleSlug: string,
): { track: Track; module: Module } | undefined {
  const track = getTrack(trackSlug);
  if (!track) return undefined;
  const module = track.modules.find((m) => m.slug === moduleSlug);
  if (!module) return undefined;
  return { track, module };
}

export function getAdjacentModules(
  track: Track,
  moduleSlug: string,
): { prev?: Module; next?: Module } {
  const idx = track.modules.findIndex((m) => m.slug === moduleSlug);
  return {
    prev: idx > 0 ? track.modules[idx - 1] : undefined,
    next: idx >= 0 && idx < track.modules.length - 1 ? track.modules[idx + 1] : undefined,
  };
}

import { tracks } from "../data";
import type { Track } from "../data/types";

export interface ProgressState {
  completedModules: string[]; // format "trackSlug/moduleSlug"
  quizScores: Record<string, number>; // key "trackSlug/moduleSlug" -> persen 0-100
  examBestScores: Record<string, number>; // key trackSlug -> persen 0-100
}

const STORAGE_KEY = "elasticcert-progress-v1";

const EMPTY: ProgressState = {
  completedModules: [],
  quizScores: {},
  examBestScores: {},
};

export function loadProgress(): ProgressState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...EMPTY };
    const parsed = JSON.parse(raw) as Partial<ProgressState>;
    return {
      completedModules: Array.isArray(parsed.completedModules) ? parsed.completedModules : [],
      quizScores: parsed.quizScores ?? {},
      examBestScores: parsed.examBestScores ?? {},
    };
  } catch {
    return { ...EMPTY };
  }
}

export function saveProgress(state: ProgressState): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // penyimpanan tidak tersedia; abaikan
  }
}

export function moduleKey(trackSlug: string, moduleSlug: string): string {
  return `${trackSlug}/${moduleSlug}`;
}

export function markModuleCompleted(
  state: ProgressState,
  trackSlug: string,
  moduleSlug: string,
): ProgressState {
  const key = moduleKey(trackSlug, moduleSlug);
  if (state.completedModules.includes(key)) return state;
  return { ...state, completedModules: [...state.completedModules, key] };
}

export function unmarkModuleCompleted(
  state: ProgressState,
  trackSlug: string,
  moduleSlug: string,
): ProgressState {
  const key = moduleKey(trackSlug, moduleSlug);
  return {
    ...state,
    completedModules: state.completedModules.filter((k) => k !== key),
  };
}

export function recordQuizScore(
  state: ProgressState,
  trackSlug: string,
  moduleSlug: string,
  percent: number,
): ProgressState {
  const key = moduleKey(trackSlug, moduleSlug);
  const prev = state.quizScores[key];
  if (prev !== undefined && prev >= percent) return state;
  return { ...state, quizScores: { ...state.quizScores, [key]: percent } };
}

export function recordExamScore(
  state: ProgressState,
  trackSlug: string,
  percent: number,
): ProgressState {
  const prev = state.examBestScores[trackSlug];
  if (prev !== undefined && prev >= percent) return state;
  return { ...state, examBestScores: { ...state.examBestScores, [trackSlug]: percent } };
}

export function isModuleCompleted(
  state: ProgressState,
  trackSlug: string,
  moduleSlug: string,
): boolean {
  return state.completedModules.includes(moduleKey(trackSlug, moduleSlug));
}

export function trackCompletion(state: ProgressState, track: Track): number {
  if (track.modules.length === 0) return 0;
  const done = track.modules.filter((m) => isModuleCompleted(state, track.slug, m.slug)).length;
  return Math.round((done / track.modules.length) * 100);
}

export function overallCompletion(state: ProgressState): number {
  const total = tracks.reduce((sum, t) => sum + t.modules.length, 0);
  if (total === 0) return 0;
  const done = tracks.reduce(
    (sum, t) => sum + t.modules.filter((m) => isModuleCompleted(state, t.slug, m.slug)).length,
    0,
  );
  return Math.round((done / total) * 100);
}

export function resetProgress(): ProgressState {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // abaikan
  }
  return { ...EMPTY };
}

import { useCallback, useState } from "react";
import {
  loadProgress,
  saveProgress,
  markModuleCompleted,
  unmarkModuleCompleted,
  recordQuizScore,
  recordExamScore,
  resetProgress as resetStoredProgress,
  type ProgressState,
} from "../lib/progress";

export function useProgress() {
  const [state, setState] = useState<ProgressState>(() => loadProgress());

  const update = useCallback((next: ProgressState) => {
    saveProgress(next);
    setState(next);
  }, []);

  const completeModule = useCallback(
    (trackSlug: string, moduleSlug: string) => {
      update(markModuleCompleted(loadProgress(), trackSlug, moduleSlug));
    },
    [update],
  );

  const uncompleteModule = useCallback(
    (trackSlug: string, moduleSlug: string) => {
      update(unmarkModuleCompleted(loadProgress(), trackSlug, moduleSlug));
    },
    [update],
  );

  const saveQuizScore = useCallback(
    (trackSlug: string, moduleSlug: string, percent: number) => {
      let next = recordQuizScore(loadProgress(), trackSlug, moduleSlug, percent);
      if (percent >= 70) {
        next = markModuleCompleted(next, trackSlug, moduleSlug);
      }
      update(next);
    },
    [update],
  );

  const saveExamScore = useCallback(
    (trackSlug: string, percent: number) => {
      update(recordExamScore(loadProgress(), trackSlug, percent));
    },
    [update],
  );

  const reset = useCallback(() => {
    update(resetStoredProgress());
  }, [update]);

  return { state, completeModule, uncompleteModule, saveQuizScore, saveExamScore, reset };
}

import { useSyncExternalStore, useCallback } from "react";
import {
  loadProgress,
  saveProgress,
  markModuleCompleted,
  unmarkModuleCompleted,
  recordQuizScore,
  recordExamScore,
  resetProgress as resetStoredProgress,
  type ProgressState,
} from "../lib/progress";

let current: ProgressState = loadProgress();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function getSnapshot(): ProgressState {
  return current;
}

function update(next: ProgressState) {
  current = next;
  saveProgress(next);
  listeners.forEach((l) => l());
}

export function useProgress() {
  const state = useSyncExternalStore(subscribe, getSnapshot);

  const completeModule = useCallback((trackSlug: string, moduleSlug: string) => {
    update(markModuleCompleted(current, trackSlug, moduleSlug));
  }, []);

  const uncompleteModule = useCallback((trackSlug: string, moduleSlug: string) => {
    update(unmarkModuleCompleted(current, trackSlug, moduleSlug));
  }, []);

  const saveQuizScore = useCallback(
    (trackSlug: string, moduleSlug: string, percent: number) => {
      let next = recordQuizScore(current, trackSlug, moduleSlug, percent);
      if (percent >= 70) {
        next = markModuleCompleted(next, trackSlug, moduleSlug);
      }
      update(next);
    },
    [],
  );

  const saveExamScore = useCallback((trackSlug: string, percent: number) => {
    update(recordExamScore(current, trackSlug, percent));
  }, []);

  const reset = useCallback(() => {
    update(resetStoredProgress());
  }, []);

  return { state, completeModule, uncompleteModule, saveQuizScore, saveExamScore, reset };
}

import { useState } from "react";
import { Link, Outlet } from "@tanstack/react-router";
import { BookOpen, Menu, X, Server, Activity, Shield } from "lucide-react";
import { tracks } from "../data";
import { useProgress } from "../hooks/useProgress";
import { overallCompletion } from "../lib/progress";

const trackIcons = { server: Server, activity: Activity, shield: Shield } as const;

export default function Layout() {
  const [menuOpen, setMenuOpen] = useState(false);
  const { state } = useProgress();
  const overall = overallCompletion(state);

  return (
    <div className="flex min-h-[100dvh] flex-col bg-slate-50 text-slate-800">
      <header className="sticky top-0 z-40 border-b border-slate-200 bg-white/90 backdrop-blur">
        <div className="mx-auto flex h-16 w-full max-w-6xl items-center justify-between gap-4 px-4 sm:px-6">
          <Link to="/" className="flex items-center gap-2 font-bold text-slate-900">
            <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-teal-600 text-white">
              <BookOpen className="h-5 w-5" aria-hidden />
            </span>
            <span className="text-lg">ElasticCert ID</span>
          </Link>

          <nav aria-label="Navigasi utama" className="hidden items-center gap-1 lg:flex">
            {tracks.map((t) => {
              const Icon = trackIcons[t.icon];
              return (
                <Link
                  key={t.slug}
                  to="/track/$trackSlug"
                  params={{ trackSlug: t.slug }}
                  className="flex items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 hover:text-slate-900 [&.active]:bg-slate-100 [&.active]:text-slate-900"
                >
                  <Icon className="h-4 w-4" aria-hidden />
                  {t.name.replace("Elastic Certified ", "")}
                </Link>
              );
            })}
            <Link
              to="/progres"
              className="rounded-lg px-3 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 hover:text-slate-900 [&.active]:bg-slate-100 [&.active]:text-slate-900"
            >
              Progres
            </Link>
          </nav>

          <div className="hidden items-center gap-2 lg:flex" aria-label="Progres keseluruhan">
            <div className="h-2 w-24 overflow-hidden rounded-full bg-slate-200">
              <div
                className="h-full rounded-full bg-teal-600 transition-all"
                style={{ width: `${overall}%` }}
              />
            </div>
            <span className="text-sm font-semibold text-slate-700">{overall}%</span>
          </div>

          <button
            type="button"
            className="flex h-11 w-11 items-center justify-center rounded-lg text-slate-700 hover:bg-slate-100 lg:hidden"
            aria-expanded={menuOpen}
            aria-label={menuOpen ? "Tutup menu" : "Buka menu"}
            onClick={() => setMenuOpen((v) => !v)}
          >
            {menuOpen ? <X className="h-6 w-6" aria-hidden /> : <Menu className="h-6 w-6" aria-hidden />}
          </button>
        </div>

        {menuOpen && (
          <nav aria-label="Navigasi seluler" className="border-t border-slate-200 bg-white px-4 py-3 lg:hidden">
            <ul className="flex flex-col gap-1">
              <li>
                <Link
                  to="/"
                  onClick={() => setMenuOpen(false)}
                  className="block rounded-lg px-3 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-100"
                >
                  Beranda
                </Link>
              </li>
              {tracks.map((t) => (
                <li key={t.slug}>
                  <Link
                    to="/track/$trackSlug"
                    params={{ trackSlug: t.slug }}
                    onClick={() => setMenuOpen(false)}
                    className="block rounded-lg px-3 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-100"
                  >
                    {t.name}
                  </Link>
                </li>
              ))}
              <li>
                <Link
                  to="/progres"
                  onClick={() => setMenuOpen(false)}
                  className="block rounded-lg px-3 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-100"
                >
                  Progres Belajar ({overall}%)
                </Link>
              </li>
            </ul>
          </nav>
        )}
      </header>

      <main className="flex-1">
        <Outlet />
      </main>

      <footer className="border-t border-slate-200 bg-white">
        <div className="mx-auto flex w-full max-w-6xl flex-col gap-4 px-4 py-8 text-sm text-slate-500 sm:flex-row sm:items-center sm:justify-between sm:px-6">
          <p>
            © {new Date().getFullYear()} ElasticCert ID — Portal belajar independen berbahasa
            Indonesia.
          </p>
          <p className="max-w-md">
            Portal ini bukan produk resmi dan tidak berafiliasi dengan Elastic. Elasticsearch dan
            Kibana adalah merek dagang Elastic N.V.
          </p>
        </div>
      </footer>
    </div>
  );
}

export default function ProgressBar({
  value,
  colorClass = "bg-teal-600",
  label,
}: {
  value: number;
  colorClass?: string;
  label?: string;
}) {
  return (
    <div className="flex items-center gap-2">
      <div
        className="h-2 flex-1 overflow-hidden rounded-full bg-slate-200"
        role="progressbar"
        aria-valuenow={value}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={label ?? "Progres"}
      >
        <div
          className={`h-full rounded-full transition-all ${colorClass}`}
          style={{ width: `${value}%` }}
        />
      </div>
      <span className="text-xs font-semibold text-slate-600">{value}%</span>
    </div>
  );
}

import type { Level } from "../data/types";

const levelStyles: Record<Level, string> = {
  Dasar: "bg-emerald-100 text-emerald-800",
  Menengah: "bg-sky-100 text-sky-800",
  Lanjutan: "bg-violet-100 text-violet-800",
  "Siap Ujian": "bg-rose-100 text-rose-800",
};

export default function Badge({ level }: { level: Level }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold ${levelStyles[level]}`}
    >
      {level}
    </span>
  );
}

import { Link } from "@tanstack/react-router";
import { ChevronRight } from "lucide-react";

export interface Crumb {
  label: string;
  to?: string;
  params?: Record<string, string>;
}

export default function Breadcrumbs({ items }: { items: Crumb[] }) {
  return (
    <nav aria-label="Navigasi lokasi" className="mb-6">
      <ol className="flex flex-wrap items-center gap-1 text-sm text-slate-500">
        {items.map((item, i) => (
          <li key={i} className="flex items-center gap-1">
            {i > 0 && <ChevronRight className="h-4 w-4 text-slate-300" aria-hidden />}
            {item.to ? (
              <Link
                to={item.to}
                params={item.params}
                className="rounded px-1 py-0.5 hover:text-teal-700 hover:underline"
              >
                {item.label}
              </Link>
            ) : (
              <span className="px-1 py-0.5 font-medium text-slate-800" aria-current="page">
                {item.label}
              </span>
            )}
          </li>
        ))}
      </ol>
    </nav>
  );
}

import { Link } from "@tanstack/react-router";
import { Compass } from "lucide-react";

export default function EmptyState({
  title,
  description,
  ctaLabel = "Kembali ke Beranda",
  ctaTo = "/",
}: {
  title: string;
  description: string;
  ctaLabel?: string;
  ctaTo?: string;
}) {
  return (
    <div className="mx-auto flex w-full max-w-2xl flex-col items-center px-4 py-20 text-center">
      <span className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-slate-100 text-slate-400">
        <Compass className="h-7 w-7" aria-hidden />
      </span>
      <h1 className="text-2xl font-bold text-slate-900">{title}</h1>
      <p className="mt-2 text-slate-600">{description}</p>
      <Link
        to={ctaTo}
        className="mt-6 inline-flex items-center justify-center rounded-lg bg-teal-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-teal-700"
      >
        {ctaLabel}
      </Link>
    </div>
  );
}

import { useState } from "react";
import { Check, Copy } from "lucide-react";
import type { CodeExample } from "../data/types";

export default function CodeBlock({ example }: { example: CodeExample }) {
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(example.code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // clipboard tidak tersedia; abaikan
    }
  }

  return (
    <figure className="overflow-hidden rounded-xl border border-slate-200 bg-slate-900">
      <figcaption className="flex items-center justify-between gap-2 border-b border-slate-700 px-4 py-2.5">
        <span className="truncate text-sm font-medium text-slate-200">{example.title}</span>
        <div className="flex items-center gap-2">
          <span className="rounded bg-slate-700 px-2 py-0.5 text-xs font-semibold uppercase text-slate-300">
            {example.lang}
          </span>
          <button
            type="button"
            onClick={handleCopy}
            className="flex h-8 items-center gap-1 rounded-md bg-slate-700 px-2.5 text-xs font-semibold text-slate-100 hover:bg-slate-600"
          >
            {copied ? (
              <>
                <Check className="h-3.5 w-3.5" aria-hidden /> Tersalin
              </>
            ) : (
              <>
                <Copy className="h-3.5 w-3.5" aria-hidden /> Salin
              </>
            )}
          </button>
        </div>
      </figcaption>
      <pre className="overflow-x-auto p-4 text-sm leading-relaxed text-slate-100">
        <code>{example.code}</code>
      </pre>
    </figure>
  );
}

import { Link } from "@tanstack/react-router";
import { Server, Activity, Shield, ArrowRight, Clock } from "lucide-react";
import type { Track } from "../data/types";
import { useProgress } from "../hooks/useProgress";
import { trackCompletion } from "../lib/progress";
import ProgressBar from "./ProgressBar";

const icons = { server: Server, activity: Activity, shield: Shield } as const;

const accents = {
  teal: {
    chip: "bg-teal-100 text-teal-700",
    bar: "bg-teal-600",
    ring: "hover:border-teal-300",
    text: "text-teal-700",
  },
  amber: {
    chip: "bg-amber-100 text-amber-700",
    bar: "bg-amber-500",
    ring: "hover:border-amber-300",
    text: "text-amber-700",
  },
  rose: {
    chip: "bg-rose-100 text-rose-700",
    bar: "bg-rose-600",
    ring: "hover:border-rose-300",
    text: "text-rose-700",
  },
} as const;

export function getAccent(color: Track["color"]) {
  return accents[color];
}

export default function TrackCard({ track }: { track: Track }) {
  const { state } = useProgress();
  const pct = trackCompletion(state, track);
  const Icon = icons[track.icon];
  const accent = accents[track.color];
  const totalMinutes = track.modules.reduce((s, m) => s + m.durationMinutes, 0);

  return (
    <Link
      to="/track/$trackSlug"
      params={{ trackSlug: track.slug }}
      className={`group flex flex-col rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition hover:shadow-md ${accent.ring}`}
    >
      <span
        className={`mb-4 flex h-12 w-12 items-center justify-center rounded-xl ${accent.chip}`}
      >
        <Icon className="h-6 w-6" aria-hidden />
      </span>
      <h3 className="text-lg font-bold text-slate-900">{track.name}</h3>
      <p className="mt-1 flex-1 text-sm leading-relaxed text-slate-600">{track.tagline}</p>
      <div className="mt-4 flex items-center gap-4 text-xs text-slate-500">
        <span>{track.modules.length} modul</span>
        <span className="flex items-center gap-1">
          <Clock className="h-3.5 w-3.5" aria-hidden />
          ±{Math.round(totalMinutes / 60)} jam belajar
        </span>
      </div>
      <div className="mt-3">
        <ProgressBar value={pct} colorClass={accent.bar} label={`Progres ${track.name}`} />
      </div>
      <span
        className={`mt-4 inline-flex items-center gap-1 text-sm font-semibold ${accent.text}`}
      >
        Jelajahi jalur
        <ArrowRight className="h-4 w-4 transition group-hover:translate-x-0.5" aria-hidden />
      </span>
    </Link>
  );
}

